/** Bounded 96×54 pixel-art scene triptych shared by the console and terminal renderers. */
export const componentMediaPng = Object.freeze({
  reference: "data:image/png;base64,",
  candidate: "data:image/png;base64,",
  difference: "data:image/png;base64,",
});

export type ComponentMediaImage = Readonly<{ label: string; src: string; width: number; height: number }>;

export const componentMediaImages: readonly ComponentMediaImage[] = Object.freeze([
  { label: "Reference", src: componentMediaPng.reference, width: 96, height: 54 },
  { label: "Candidate", src: componentMediaPng.candidate, width: 96, height: 54 },
  { label: "Difference", src: componentMediaPng.difference, width: 96, height: 54 },
]);

const MEDIA_WIDTH = 96;
const MEDIA_HEIGHT = 54;
const stars = [[7, 7], [14, 15], [23, 5], [34, 12], [45, 6], [56, 16], [66, 7], [86, 17], [91, 5], [4, 23], [49, 23]] as const;

function scenePixels(candidate: boolean): Uint8Array {
  const pixels = new Uint8Array(MEDIA_WIDTH * MEDIA_HEIGHT * 4);
  const set = (x: number, y: number, color: readonly number[]) => {
    if (x < 0 || y < 0 || x >= MEDIA_WIDTH || y >= MEDIA_HEIGHT) return;
    pixels.set([...color, 255], (y * MEDIA_WIDTH + x) * 4);
  };
  for (let y = 0; y < MEDIA_HEIGHT; y += 1) for (let x = 0; x < MEDIA_WIDTH; x += 1) {
    const mix = y / 38;
    const stripe = (y % 4 === 0 ? 5 : 0) + (x % 11 === 0 ? 3 : 0);
    set(x, y, y < 38
      ? [Math.round(8 + 14 * mix), Math.round(15 + 22 * mix), Math.round(38 + 34 * mix)]
      : [7 + stripe, 24 + stripe, 31 + stripe]);
  }
  for (const [x, y] of stars) {
    set(x, y, [190, 218, 255]);
    if ((x + y) % 3 === 0) set(x + 1, y, [92, 128, 178]);
  }
  const moonX = candidate ? 78 : 75;
  for (let y = 3; y < 18; y += 1) for (let x = 68; x < 86; x += 1) {
    const distance = Math.hypot(x - moonX, y - 10);
    if (distance < 6) set(x, y, distance < 4.5 ? [248, 220, 144] : [205, 190, 143]);
  }
  for (let x = 0; x < MEDIA_WIDTH; x += 1) {
    const ridge = Math.min(
      33 - Math.max(0, 14 - Math.abs(x - 27) * 0.55),
      35 - Math.max(0, 11 - Math.abs(x - 67) * 0.45),
    );
    for (let y = Math.max(18, Math.floor(ridge)); y < 38; y += 1) {
      set(x, y, y < ridge + 2.4 ? [111, 139, 166] : y < 31 ? [36, 60, 78] : [23, 44, 55]);
    }
  }
  for (let x = 9; x <= 31; x += 1) for (let y = Math.floor(23 + Math.abs(x - 20) * 0.55); y < 31; y += 1) set(x, y, [66, 42, 41]);
  for (let y = 30; y <= 45; y += 1) for (let x = 12; x <= 28; x += 1) set(x, y, [112, 71, 46]);
  for (let y = 34; y <= 44; y += 1) for (let x = 14; x <= 18; x += 1) set(x, y, [48, 37, 35]);
  const windowX = candidate ? 22 : 21;
  for (let y = 34; y <= 39; y += 1) for (let x = windowX; x <= windowX + 4; x += 1) set(x, y, candidate ? [76, 174, 233] : [249, 190, 83]);
  for (let x = windowX; x <= windowX + 4; x += 1) set(x, 37, [54, 50, 48]);
  for (let y = 34; y <= 39; y += 1) set(windowX + 2, y, [54, 50, 48]);
  for (let y = 20; y < 29; y += 1) for (let x = 25; x < 28; x += 1) set(x, y, [45, 42, 48]);
  for (const center of [42, 88]) {
    for (let y = 23; y < 46; y += 1) {
      const half = Math.floor((y - 23) * 0.32);
      for (let x = center - half; x <= center + half; x += 1) if ((y - 23) % 7 < 5) set(x, y, [16, 57, 49]);
    }
    for (let y = 38; y < 48; y += 1) set(center, y, [61, 42, 32]);
  }
  const boatX = candidate ? 67 : 65;
  for (let x = boatX; x < boatX + 13; x += 1) set(x, 43, [138, 72, 45]);
  for (let x = boatX + 2; x < boatX + 11; x += 1) set(x, 44, [74, 45, 37]);
  for (let y = 35; y < 43; y += 1) set(boatX + 6, y, [194, 205, 198]);
  for (let x = boatX + 6; x < boatX + 12; x += 1) for (let y = 36 + Math.floor((x - boatX - 6) * 0.75); y < 42; y += 1) set(x, y, [214, 113, 73]);
  for (let x = 50; x <= 60; x += 1) set(x, 48, [82, 47, 34]);
  const flameTop = candidate ? 37 : 39;
  for (let y = flameTop; y < 48; y += 1) {
    const half = Math.max(0, Math.floor((48 - y) * 0.48));
    for (let x = 55 - half; x <= 55 + half; x += 1) {
      const inner = Math.abs(x - 55) < Math.max(1, half - 1) && y > flameTop + 3;
      set(x, y, inner ? [255, 220, 92] : y < 43 ? [241, 87, 50] : [248, 142, 48]);
    }
  }
  for (let x = 0; x < MEDIA_WIDTH; x += 7) {
    set(x, 50, [28, 64, 54]);
    set(x + 1, 49, [28, 64, 54]);
  }
  for (let x = 31; x < 84; x += 1) if (x % 9 < 5) set(x, 51, [25, 63, 72]);
  return pixels;
}

const referencePixels = scenePixels(false);
const candidatePixels = scenePixels(true);
const differencePixels = new Uint8Array(MEDIA_WIDTH * MEDIA_HEIGHT * 4);
for (let index = 0; index < differencePixels.length; index += 4) {
  const delta = Math.max(
    Math.abs(referencePixels[index]! - candidatePixels[index]!),
    Math.abs(referencePixels[index + 1]! - candidatePixels[index + 1]!),
    Math.abs(referencePixels[index + 2]! - candidatePixels[index + 2]!),
  );
  differencePixels.set(delta
    ? [Math.min(255, 96 + delta * 2), Math.min(220, 30 + delta), Math.min(150, 24 + Math.floor(delta / 3)), 255]
    : [5, 8, 14, 255], index);
}

export const componentMediaRgba = Object.freeze({
  reference: { width: MEDIA_WIDTH, height: MEDIA_HEIGHT, pixels: referencePixels },
  candidate: { width: MEDIA_WIDTH, height: MEDIA_HEIGHT, pixels: candidatePixels },
  difference: { width: MEDIA_WIDTH, height: MEDIA_HEIGHT, pixels: differencePixels },
});

export function componentMediaPixelsForSource(source: string) {
  const key = (Object.keys(componentMediaPng) as Array<keyof typeof componentMediaPng>)
    .find((name) => componentMediaPng[name] === source);
  return key ? componentMediaRgba[key] : null;
}

/** Browser-safe deterministic source identity used by paired tests and evidence. */
export function componentMediaDigest(source: string): string {
  let hash = 0x811c9dc5;
  for (let index = 0; index < source.length; index += 1) {
    hash ^= source.charCodeAt(index);
    hash = Math.imul(hash, 0x01000193);
  }
  return (hash >>> 0).toString(16).padStart(8, "0");
}
